(() => {
    const loader = document.querySelector('.loader-admongas');
    if (!loader) return;

    const inicio = performance.now();
    window.addEventListener('load', () => {
        const espera = Math.max(0, 300 - (performance.now() - inicio));
        window.setTimeout(() => {
            loader.style.display = 'none';
        }, espera);
    }, { once: true });
})();
